# ===== Result Enums =====
class MavlinkDirectServerResult(IntEnum):
    """Possible results returned for action requests."""

    UNKNOWN = 0
    SUCCESS = 1
    ERROR = 2
    INVALID_MESSAGE = 3
    INVALID_FIELD = 4
    CONNECTION_ERROR = 5
    NO_SYSTEM = 6
    TIMEOUT = 7


class MavlinkDirectServerError(MavsdkError):
    """Raised when a MavlinkDirectServer request fails.

    Attributes
    ----------
    result : MavlinkDirectServerResult
        The result the request failed with.
    origin : str
        The method that failed.
    params : tuple
        The arguments the method was called with.
    """

    def __init__(self, result, origin, *params):
        super().__init__(result, origin, *params)
        self.result = result
        self.origin = origin
        self.params = params

    def __str__(self):
        return f"{self.result.name}; origin: {self.origin}; params: {self.params}"


# ===== Internal C Structures =====
class MavlinkMessageCStruct(ctypes.Structure):
    """
    Internal C structure for MavlinkMessage.
    Used only for C library communication.
    """

    _fields_ = [
        ("message_name", ctypes.c_char_p),
        ("system_id", ctypes.c_uint32),
        ("component_id", ctypes.c_uint32),
        ("target_system_id", ctypes.c_uint32),
        ("target_component_id", ctypes.c_uint32),
        ("fields_json", ctypes.c_char_p),
    ]


# ===== Structures =====
class MavlinkMessage:
    """
    A complete MAVLink message with all header information and fields
    """

    def __init__(
        self,
        message_name=None,
        system_id=None,
        component_id=None,
        target_system_id=None,
        target_component_id=None,
        fields_json=None,
    ):
        self.message_name = message_name
        self.system_id = system_id
        self.component_id = component_id
        self.target_system_id = target_system_id
        self.target_component_id = target_component_id
        self.fields_json = fields_json

    @classmethod
    def from_c_struct(cls, c_struct):
        """Convert from C structure to Python object"""
        instance = cls()
        instance.message_name = c_struct.message_name.decode("utf-8")
        instance.system_id = c_struct.system_id
        instance.component_id = c_struct.component_id
        instance.target_system_id = c_struct.target_system_id
        instance.target_component_id = c_struct.target_component_id
        instance.fields_json = c_struct.fields_json.decode("utf-8")
        return instance

    def to_c_struct(self):
        """Convert to C structure for C library calls"""
        c_struct = MavlinkMessageCStruct()
        c_struct.message_name = self.message_name.encode("utf-8")
        c_struct.system_id = self.system_id
        c_struct.component_id = self.component_id
        c_struct.target_system_id = self.target_system_id
        c_struct.target_component_id = self.target_component_id
        c_struct.fields_json = self.fields_json.encode("utf-8")
        return c_struct

    def __str__(self):
        fields = []
        fields.append(f"message_name={self.message_name}")
        fields.append(f"system_id={self.system_id}")
        fields.append(f"component_id={self.component_id}")
        fields.append(f"target_system_id={self.target_system_id}")
        fields.append(f"target_component_id={self.target_component_id}")
        fields.append(f"fields_json={self.fields_json}")
        return f"MavlinkMessage({', '.join(fields)})"


# ===== Plugin =====
class MavlinkDirectServer:
    """Enable direct MAVLink communication using libmav from a server component.

    Unlike MavlinkDirect, this does not require a discovered system: it sends from
    the local server component, which makes it suitable for broadcasting messages
    (e.g. as an autopilot or custom component) without a connected counterpart."""

    def __init__(self, server_component):
        self._lib = _cmavsdk_lib
        self._handle = None
        self._callbacks = []  # Keep references to prevent GC
        # Stream subscriptions, by handle: the trampoline to keep alive and the
        # unsubscribe to call for it. destroy() releases whatever is left. Entries
        # are taken under the lock below, so a handle goes to either destroy() or
        # one unsubscribe, never both. The C call then happens outside the lock,
        # which waits for a running callback -- and a callback may unsubscribe.
        self._subscriptions = {}
        # destroy() can be reached from any thread: explicitly, from the owner
        # tearing down, or from __del__ whenever the garbage collector happens to
        # run. Without this lock two of them can both find a live handle and
        # destroy the same plugin twice, which corrupts the heap.
        self._destroy_lock = threading.Lock()

        if server_component is None:
            raise ValueError("server_component cannot be None")

        component_handle = server_component._handle

        if not component_handle:
            raise ValueError("server_component handle is null")

        self._handle = self._lib.mavsdk_mavlink_direct_server_create(component_handle)

        if not self._handle:
            raise RuntimeError(
                "Failed to create MavlinkDirectServer plugin - C function returned null handle"
            )

        server_component._track_plugin(self)

    def send_message(self, message):
        """Get send_message (blocking)"""

        result_code = self._lib.mavsdk_mavlink_direct_server_send_message(
            self._require_handle(),
            message.to_c_struct(),
        )
        result = MavlinkDirectServerResult(result_code)
        if result != MavlinkDirectServerResult.SUCCESS:
            raise MavlinkDirectServerError(result, "send_message()", message)

        return result

    def subscribe_message(
        self, message_name, callback: Callable, user_data: Any = None
    ):
        """Subscribe to incoming MAVLink messages.

        This provides direct access to incoming MAVLink messages. Use an empty string
        in message_name to subscribe to all messages, or specify a message name
        (e.g., "HEARTBEAT") to filter for specific message types. Unlike the
        MavlinkDirect (client) plugin, this is not scoped to a single system: it
        receives matching messages from all systems."""

        def c_callback(c_data, ud):
            try:
                py_data = MavlinkMessage.from_c_struct(c_data)

                self._lib.mavsdk_mavlink_direct_server_mavlink_message_destroy(
                    ctypes.byref(c_data)
                )

                callback(py_data, user_data)

            except Exception as e:
                print(f"Error in message callback: {e}")

        cb = MessageCallback(c_callback)

        _subscription = self._lib.mavsdk_mavlink_direct_server_subscribe_message(
            self._require_handle(),
            message_name.encode("utf-8")
            if isinstance(message_name, str)
            else message_name,
            cb,
            None,
        )

        self._subscriptions[_subscription] = (
            cb,
            self._lib.mavsdk_mavlink_direct_server_unsubscribe_message,
        )

        return _subscription

    def unsubscribe_message(self, handle: ctypes.c_void_p):
        """Unsubscribe from message

        Idempotent. Does nothing once the plugin is destroyed, which unsubscribes
        already.
        """
        with self._destroy_lock:
            if not self._handle:
                return
            if self._subscriptions.pop(handle, None) is None:
                return
            _plugin_handle = self._handle

        self._lib.mavsdk_mavlink_direct_server_unsubscribe_message(
            _plugin_handle, handle
        )

    def load_custom_xml(self, xml_content):
        """Get load_custom_xml (blocking)"""

        result_code = self._lib.mavsdk_mavlink_direct_server_load_custom_xml(
            self._require_handle(),
            xml_content.encode("utf-8")
            if isinstance(xml_content, str)
            else xml_content,
        )
        result = MavlinkDirectServerResult(result_code)
        if result != MavlinkDirectServerResult.SUCCESS:
            raise MavlinkDirectServerError(result, "load_custom_xml()", xml_content)

        return result

    def _require_handle(self) -> ctypes.c_void_p:
        """Fail loudly rather than dereferencing a null handle in C.

        The plugin is destroyed together with its owner, which a caller holding on
        to it may not expect, so using it afterwards would otherwise segfault in
        the C wrapper.
        """
        if not self._handle:
            raise RuntimeError(
                "MavlinkDirectServer has been destroyed (its "
                "server component or "
                "Mavsdk was destroyed, or destroy() was called explicitly)"
            )
        return self._handle

    def destroy(self):
        """Destroy the plugin instance. Idempotent and safe from any thread."""
        with self._destroy_lock:
            handle, self._handle = self._handle, None
            # Taken under the same lock as the handle, so an unsubscribe racing
            # this either gets its entry and releases it itself, or finds the
            # plugin already gone. Neither path releases a handle twice.
            _subscriptions = list(self._subscriptions.items())
            self._subscriptions.clear()

        if handle:
            # The C wrapper does not track these, so release them here. unsubscribe()
            # waits for a running callback, so this cannot race one. The snapshot
            # also holds the trampolines until past destroy, so a late callback
            # cannot jump into collected memory.
            for _subscription, (_cb, _unsubscribe) in _subscriptions:
                _unsubscribe(handle, _subscription)

            self._lib.mavsdk_mavlink_direct_server_destroy(handle)
            self._callbacks.clear()

    def __del__(self):
        self.destroy()


